	["Dire"] = "Say", ["Groupe ou raid"] = "Party or raid", ["Seuil de mana faible (%)"] = "Low mana threshold (%)", ["Seuil de mana remontée (%)"] = "Mana back threshold (%)", ["Tester"] = "Test",
